    $('feedback')?.addEventListener('click',()=>openEditor('App feedback',field('What happened, or what would make this easier?','feedback-message',{textarea:true})+attachmentField()+'<p class="muted">Submitted to your shared feedback inbox for Vinny and future build reviews. This does not automatically start a code change.</p>',async()=>action({type:'feedback',message:value('feedback-message'),assetId:await attachment(),screen:tab,appVersion:'shopping-preview-1'}),'Send feedback'));
    document.querySelectorAll('[data-feedback-status]').forEach(b=>b.onclick=()=>openEditor('Feedback update',field('Status','feedback-status',{select:['new','reviewing','planned','fixed'].map(x=>[x,x])})+field('Reply','feedback-reply',{textarea:true})+field('Actual release, required for fixed','feedback-release'),()=>action({type:'feedback-status',id:b.dataset.feedbackStatus,status:value('feedback-status'),message:value('feedback-reply'),release:value('feedback-release')})));
