    document.querySelectorAll('[data-add-offer]').forEach(b=>b.onclick=()=>{const i=item(b.dataset.addOffer);openEditor('Save an official offer link',field('Provider','offer-provider',{select:[['jewel','Jewel for U'],['ibotta','Ibotta']]})+field('Offer description','offer-description',{required:true})+field('Exact size / count / eligibility requirements','offer-conditions',{textarea:true,required:true})+field('Official link','offer-url',{type:'url',required:true})+field('Expiration, if known (your device’s local time)','offer-expiry',{type:'datetime-local'})+'<p class="muted">Saving this link records your review, not a verified account connection. Activation remains manual.</p>',()=>action({type:'offer',id:i.id,itemRevision:i.revision,provider:value('offer-provider'),description:value('offer-description'),conditions:value('offer-conditions'),url:value('offer-url'),expiresAt:value('offer-expiry')?new Date(value('offer-expiry')).toISOString():''}));});
    document.querySelectorAll('[data-clip]').forEach(b=>b.onclick=()=>action({type:'clip-confirmation',id:b.dataset.clip,offerId:b.dataset.offer,activated:b.dataset.activated==='true'}).catch(e=>toast(e.message)));
